<script setup lang="ts">
import { reactive, ref, watch } from 'vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import PasswordInput from '@/components/PasswordInput.vue';
import PaginationControls from '@/components/PaginationControls.vue';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse, Pagination, PlatformSettings, StaffAccount } from '@/types/api';
const props = defineProps<{ section: 'overview' | 'admins' | 'settings' }>();
interface Overview { admins: { total: number; active: number; disabled: number; pendingInvitations: number }; audit: { id: string; action: string; actorId: string | null; targetId: string | null; createdAt: string }[]; settings: PlatformSettings; }
const overview = ref<Overview | null>(null), settings = ref<PlatformSettings | null>(null), admins = ref<StaffAccount[]>([]), selected = ref<StaffAccount | null>(null), pagination = ref<Pagination | null>(null);
const busy = ref(false), loading = ref(false), error = ref(''), notice = ref(''), page = ref(1), search = ref(''), active = ref('');
const configuration = reactive({ platformName: '', emailEnabled: false, mediaEnabled: false, currentPassword: '' });
const invite = reactive({ fullName: '', email: '', currentPassword: '' }), edit = reactive({ fullName: '', currentPassword: '' });
async function load(next = 1) {
  page.value = next; loading.value = true; error.value = '';
  try {
    if (props.section === 'overview') overview.value = (await api.get<ApiResponse<Overview>>('/super-admin/dashboard')).data.data;
    if (props.section === 'settings') { settings.value = (await api.get<ApiResponse<PlatformSettings>>('/super-admin/settings')).data.data; Object.assign(configuration, { platformName: settings.value.platformName, emailEnabled: settings.value.emailEnabled, mediaEnabled: settings.value.mediaEnabled }); }
    if (props.section === 'admins') { const response = await api.get<ApiResponse<StaffAccount[]>>('/super-admin/admins', { params: { page: next, search: search.value, active: active.value || undefined } }); admins.value = response.data.data; pagination.value = response.data.pagination; }
  } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; }
}
async function action(kind: 'invite' | 'settings' | 'update' | 'status') {
  busy.value = true; error.value = ''; notice.value = '';
  try {
    if (kind === 'invite') { await api.post('/super-admin/admins', invite); Object.assign(invite, { fullName: '', email: '', currentPassword: '' }); notice.value = 'Admin invitation accepted by the mail server. The invitee must verify it and set a password.'; }
    if (kind === 'settings') { await api.patch('/super-admin/settings', configuration); configuration.currentPassword = ''; notice.value = 'Platform settings saved.'; }
    if (kind === 'update' && selected.value) { await api.patch(`/super-admin/admins/${selected.value.id}`, edit); selected.value = null; edit.currentPassword = ''; notice.value = 'Admin information updated.'; }
    if (kind === 'status' && selected.value) { await api.patch(`/super-admin/admins/${selected.value.id}/${selected.value.isActive ? 'disable' : 'enable'}`, { currentPassword: edit.currentPassword }); selected.value = null; edit.currentPassword = ''; notice.value = 'Admin status updated. Previous sessions have been revoked.'; }
    await load(page.value);
  } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
async function details(id: string) { try { selected.value = (await api.get<ApiResponse<StaffAccount>>(`/super-admin/admins/${id}`)).data.data; edit.fullName = selected.value.staffProfile?.fullName ?? ''; edit.currentPassword = ''; } catch (e) { error.value = errorMessage(e); } }
watch(() => props.section, () => { selected.value = null; error.value = ''; notice.value = ''; configuration.currentPassword = ''; invite.currentPassword = ''; edit.currentPassword = ''; void load(); }, { immediate: true });
</script>
<template><DashboardLayout><section class="mx-auto max-w-6xl space-y-6 p-5 lg:p-10"><h1 class="text-h1">{{ section === 'overview' ? 'SuperAdmin dashboard' : section === 'admins' ? 'Admin accounts' : 'Platform settings' }}</h1><p class="text-secondary">Manage platform infrastructure and administrative access. School operations are assigned to Admin accounts.</p><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><p v-if="loading" role="status">Loading…</p><button v-if="error" class="secondary-button" @click="load(page)">Retry</button>
<template v-if="section === 'overview' && overview"><div class="grid gap-5 sm:grid-cols-2 lg:grid-cols-4"><section v-for="(value, key) in overview.admins" :key="key" class="space-y-3 border bg-white p-6"><h2 class="font-semibold">{{ key === 'pendingInvitations' ? 'Pending invitations' : `${key} Admins` }}</h2><p class="text-3xl">{{ value }}</p></section></div><section class="space-y-3 border bg-white p-6"><h2 class="text-h2">Integration configuration</h2><p>Email: {{ overview.settings.emailEnabled ? 'Enabled' : 'Disabled' }} · {{ overview.settings.email.configured ? 'Configured' : 'Server configuration required' }}</p><p>Image uploads ({{ overview.settings.media?.provider === 'local' ? 'Server storage' : 'Cloudinary' }}): {{ overview.settings.mediaEnabled ? 'Enabled' : 'Disabled' }} · {{ overview.settings.media?.configured ? 'Configured' : 'Server configuration required' }}</p><p class="text-sm text-secondary">Configuration status does not establish external service health or inbox delivery.</p><RouterLink to="/super-admin/settings" class="inline-block underline">Manage settings</RouterLink></section><section class="space-y-4 border bg-white p-6"><h2 class="text-h2">Recent audit history</h2><p v-if="!overview.audit.length">No audit activity recorded.</p><article v-for="record in overview.audit" :key="record.id" class="border-t pt-3"><h3 class="font-semibold">{{ record.action.replace(/_/g, ' ') }}</h3><p class="break-all text-sm text-secondary">{{ new Date(record.createdAt).toLocaleString() }} · Actor {{ record.actorId ?? 'Operator' }} · Target {{ record.targetId ?? 'Platform' }}</p></article></section></template>
<template v-if="section === 'settings' && settings"><form class="space-y-5 border bg-white p-6" @submit.prevent="action('settings')"><label for="platform-name" class="field-label">Platform name</label><input id="platform-name" v-model.trim="configuration.platformName" required minlength="2" maxlength="150" class="field-input"><label class="flex items-center gap-3"><input v-model="configuration.emailEnabled" type="checkbox">Enable email delivery</label><p class="text-sm">{{ settings.email.configured ? `Configured sender: ${settings.email.sender}` : 'Configure an email provider on the server to enable delivery.' }}</p><p class="text-sm text-secondary">{{ settings.email.status }}</p><label class="flex items-center gap-3"><input v-model="configuration.mediaEnabled" type="checkbox">Enable image uploads</label><p class="text-sm">{{ settings.media?.provider === 'local' ? 'Server storage is configured. Cloudinary credentials are not needed.' : settings.cloudinary.configured ? `Configured cloud: ${settings.cloudinary.cloudName}` : 'Configure server storage or Cloudinary in the backend environment.' }}</p><p class="text-sm">{{ settings.cloudinary.formats.join(', ') }} · maximum {{ settings.cloudinary.maxBytes / 1024 / 1024 }} MB</p><p class="text-sm text-secondary">{{ settings.media?.status || settings.cloudinary.status }}</p><label for="settings-password" class="field-label">Current password to confirm settings</label><PasswordInput id="settings-password" v-model="configuration.currentPassword" required autocomplete="current-password"/><button class="primary-button" :disabled="busy">Save platform settings</button></form></template>
<template v-if="section === 'admins'"><form class="space-y-5 border bg-white p-6" @submit.prevent="action('invite')"><h2 class="text-h2">Invite an Admin</h2><p>The account becomes active only after its recipient consumes the emailed invitation and creates a password. Email delivery must be enabled.</p><label for="invite-name" class="field-label">Admin full name</label><input id="invite-name" v-model.trim="invite.fullName" class="field-input" required minlength="2" maxlength="150"><label for="invite-email" class="field-label">Admin email</label><input id="invite-email" v-model.trim="invite.email" type="email" class="field-input" required maxlength="254"><label for="invite-password" class="field-label">Your current password to invite an Admin</label><PasswordInput id="invite-password" v-model="invite.currentPassword" required autocomplete="current-password"/><button class="primary-button" :disabled="busy">Send Admin invitation</button></form><form class="flex flex-wrap items-end gap-3 border bg-white p-5" @submit.prevent="load()"><div class="min-w-0 flex-1"><label for="admin-search" class="field-label">Search Admin name or email</label><input id="admin-search" v-model.trim="search" maxlength="150" class="field-input"></div><div><label for="admin-active" class="field-label">Account status</label><select id="admin-active" v-model="active" class="field-input"><option value="">All</option><option value="true">Active</option><option value="false">Disabled</option></select></div><button class="secondary-button" :disabled="loading">Search Admins</button></form><article v-for="admin in admins" :key="admin.id" class="space-y-3 border bg-white p-6"><h2 class="text-h2">{{ admin.staffProfile?.fullName || admin.email }}</h2><p class="break-all">{{ admin.email }}</p><p>{{ admin.isActive ? 'Active' : 'Disabled' }}</p><button class="secondary-button" :disabled="busy" @click="details(admin.id)">View Admin details</button></article><p v-if="!loading && !admins.length">No Admin accounts match your search.</p><PaginationControls :page="page" :pagination="pagination" :busy="loading || busy" @change="load"/><form v-if="selected" class="space-y-5 border border-primary bg-white p-6" @submit.prevent="action('update')"><h2 class="text-h2">Manage Admin</h2><p class="break-all">{{ selected.email }} · {{ selected.isActive ? 'Active' : 'Disabled' }}</p><label for="admin-name" class="field-label">Full name</label><input id="admin-name" v-model.trim="edit.fullName" required minlength="2" maxlength="150" class="field-input"><label for="admin-password" class="field-label">Your current password to confirm changes</label><PasswordInput id="admin-password" v-model="edit.currentPassword" required autocomplete="current-password"/><p class="text-sm">Disabling blocks login and revokes existing sessions. Historical school records are preserved.</p><div class="flex flex-wrap gap-3"><button class="primary-button" :disabled="busy">Save Admin information</button><button type="button" class="secondary-button" :disabled="busy || !edit.currentPassword" @click="action('status')">{{ selected.isActive ? 'Disable Admin' : 'Enable Admin' }}</button><button type="button" class="secondary-button" @click="selected = null; edit.currentPassword = ''">Close details</button></div></form></template></section></DashboardLayout></template>
